description:
Root of the compound component: holds the edge (`side:`) and the drawer options and shares them with its parts. Renders a `display: contents` wrapper for the Stimulus controller, so it doesn't affect layout.

  Drawer(side: :right) do
    DrawerTrigger { |trigger| Button(**trigger, variant: :outline) { "Open drawer" } }
    DrawerContent do
      DrawerHeader do
        DrawerTitle { "Notifications" }
        DrawerDescription { "Choose what you want to be notified about." }
      end
      DrawerBody { ... }
      DrawerFooter do
        DrawerClose { |close| Button(**close) { "Save" } }
        DrawerClose { |close| Button(**close, variant: :outline) { "Cancel" } }
      end
    end
  end

DrawerTrigger.description:
The button that opens the drawer. A block taking an argument receives the trigger attributes to put on your own element (Appica's `render` prop):

  DrawerTrigger { |trigger| Button(**trigger, variant: :outline) { "Open" } }
  DrawerTrigger(class: "underline") { "Open" }   # plain <button>

examples.code:
phlex do
  Drawer(side:, disable_pointer_dismissal:, default_open:, modal:) do
    DrawerTrigger { |trigger| Button(**trigger, variant: :outline) { "Open drawer" } }
    DrawerContent(close_button:, frame:, class: ("mx-auto max-w-2xl" if side.to_sym.in?(%i[ top bottom ]))) do
      DrawerHeader do
        DrawerTitle { "Notifications" }
        DrawerDescription { "Choose what you want to be notified about." }
      end
      DrawerBody do
        p { "Drag the handle or swipe toward the edge to dismiss. On the #{side} edge the panel slides in from there." }
      end
      DrawerFooter do
        DrawerClose { |close| Button(**close) { "Save" } }
        DrawerClose { |close| Button(**close, variant: :outline) { "Cancel" } }
      end
    end
  end
end
